?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý bài viết</title><link rel="stylesheet" href="../css/style.css"></head><body><main class="admin-wrap"><section class="admin-panel admin-wide"><div class="admin-top"><h1>Quản lý blog</h1><a href="logout.php">Đăng xuất</a></div><p>Xin chào <?= e($_SESSION['blog_admin_name'] ?? 'quản trị viên') ?> · <a href="../blog.php" target="_blank">Xem blog</a></p><p><a class="go admin-new" href="edit.php">+ Viết bài mới</a></p><div class="admin-table"><?php if(!$posts): ?><p>Chưa có bài viết nào.</p><?php else: ?><table><thead><tr><th>Bài viết</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($posts as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= $p['status']==='published'?'Đã đăng':'Bản nháp' ?></td><td><a href="edit.php?id=<?= (int)$p['id'] ?>">Sửa</a> · <form class="inline-form" method="post" action="delete.php" onsubmit="return confirm('Xóa bài viết này?')"><input type="hidden" name="csrf" value="<?= e($_SESSION['csrf']) ?>"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="lnk" type="submit">Xóa</button></form></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></section></main></body></html>
